import sys
from pathlib import Path

import httpx
import pytest
from fastmcp.server.providers.openapi import OpenAPIProvider

PROJECT_ROOT = Path(__file__).resolve().parents[1]
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))


OPENAPI_SPEC = {
    "openapi": "3.1.0",
    "info": {"title": "FastMCP security regression", "version": "1.0.0"},
    "paths": {
        "/api/v1/users/{id}/profile": {
            "get": {
                "operationId": "get_user_profile",
                "parameters": [
                    {
                        "name": "id",
                        "in": "path",
                        "required": True,
                        "schema": {"type": "string"},
                    }
                ],
                "responses": {"200": {"description": "ok"}},
            }
        }
    },
}


@pytest.mark.asyncio
async def test_openapi_provider_percent_encodes_path_parameters():
    captured = {}

    async def handler(request: httpx.Request) -> httpx.Response:
        captured["path"] = request.url.path
        captured["raw_path"] = request.url.raw_path.decode("ascii")
        captured["authorization"] = request.headers.get("authorization")
        return httpx.Response(200, json={"ok": True})

    transport = httpx.MockTransport(handler)
    async with httpx.AsyncClient(
        base_url="http://backend.local/",
        headers={"Authorization": "Bearer admin_secret"},
        transport=transport,
    ) as client:
        provider = OpenAPIProvider(openapi_spec=OPENAPI_SPEC, client=client)
        tool = await provider.get_tool("get_user_profile")

        assert tool is not None

        result = await tool.run({"id": "../../../admin/delete-all?"})

    assert result.structured_content == {"ok": True}
    assert captured["authorization"] == "Bearer admin_secret"
    assert captured["path"].startswith("/api/v1/users/")
    assert captured["raw_path"].startswith("/api/v1/users/%2E%2E%2F")
    assert captured["raw_path"].endswith("/profile")

from helpers.api import ApiHandler, Request, Response
from helpers.backup import BackupService


class BackupTest(ApiHandler):
    @classmethod
    def requires_auth(cls) -> bool:
        return True

    @classmethod
    def requires_loopback(cls) -> bool:
        return False

    async def process(self, input: dict, request: Request) -> dict | Response:
        try:
            # Get input parameters
            include_patterns = input.get("include_patterns", [])
            exclude_patterns = input.get("exclude_patterns", [])
            include_hidden = input.get("include_hidden", True)
            max_files = input.get("max_files", 1000)

            # Support legacy string patterns format for backward compatibility
            patterns_string = input.get("patterns", "")
            if patterns_string and not include_patterns:
                # Parse patterns string into arrays
                lines = [line.strip() for line in patterns_string.split('\n') if line.strip() and not line.strip().startswith('#')]
                for line in lines:
                    if line.startswith('!'):
                        exclude_patterns.append(line[1:])
                    else:
                        include_patterns.append(line)

            if not include_patterns:
                return {
                    "success": True,
                    "files": [],
                    "total_count": 0,
                    "truncated": False
                }

            # Create metadata object for testing
            metadata = {
                "include_patterns": include_patterns,
                "exclude_patterns": exclude_patterns,
                "include_hidden": include_hidden
            }

            backup_service = BackupService()
            matched_files = await backup_service.test_patterns(metadata, max_files=max_files)
            truncated = max_files is not None and len(matched_files) >= max_files

            return {
                "success": True,
                "files": matched_files,
                "total_count": len(matched_files),
                "truncated": truncated
            }

        except Exception as e:
            return {
                "success": False,
                "error": str(e)
            }

from helpers.api import ApiHandler, Request, Response
from helpers.backup import BackupService
from werkzeug.datastructures import FileStorage


class BackupInspect(ApiHandler):
    @classmethod
    def requires_auth(cls) -> bool:
        return True

    @classmethod
    def requires_loopback(cls) -> bool:
        return False

    async def process(self, input: dict, request: Request) -> dict | Response:
        # Handle file upload
        if 'backup_file' not in request.files:
            return {"success": False, "error": "No backup file provided"}

        backup_file: FileStorage = request.files['backup_file']
        if backup_file.filename == '':
            return {"success": False, "error": "No file selected"}

        try:
            backup_service = BackupService()
            metadata = await backup_service.inspect_backup(backup_file)

            return {
                "success": True,
                "metadata": metadata,
                "files": metadata.get("files", []),
                "include_patterns": metadata.get("include_patterns", []),
                "exclude_patterns": metadata.get("exclude_patterns", []),
                "default_patterns": metadata.get("backup_config", {}).get("default_patterns", ""),
                "agent_zero_version": metadata.get("agent_zero_version", "unknown"),
                "timestamp": metadata.get("timestamp", ""),
                "backup_name": metadata.get("backup_name", ""),
                "total_files": metadata.get("total_files", len(metadata.get("files", []))),
                "backup_size": metadata.get("backup_size", 0),
                "include_hidden": metadata.get("include_hidden", True),
                "files_in_archive": metadata.get("files_in_archive", []),
                "checksums": {}  # Will be added if needed
            }

        except Exception as e:
            return {
                "success": False,
                "error": str(e)
            }

"""Test inbound and outbound email connectivity for a handler config."""

import asyncio

from helpers.api import ApiHandler, Request
from helpers.errors import format_error

from plugins._email_integration.helpers.imap_client import (
    connect_exchange,
    connect_imap,
    disconnect_imap,
    get_highest_uid,
)
from plugins._email_integration.helpers.smtp_client import SmtpConfig, test_smtp, send_reply


class TestConnection(ApiHandler):

    async def process(self, input: dict, request: Request) -> dict:
        handler = input.get("handler", {})
        results: list[dict] = []
        account_type = handler.get("account_type", "imap")

        if account_type == "exchange":
            await self._test_exchange(handler, results)
        else:
            await self._test_imap(handler, results)
        await self._test_smtp(handler, results)
        if all(r["ok"] for r in results):
            await self._test_send(handler, results)

        ok = all(r["ok"] for r in results)
        return {"success": ok, "results": results}

    async def _test_imap(self, handler: dict, results: list[dict]):
        try:
            client = await connect_imap(
                server=handler.get("imap_server", ""),
                port=int(handler.get("imap_port", 993)),
                username=handler.get("username", ""),
                password=handler.get("password", ""),
            )
            await get_highest_uid(client)
            await disconnect_imap(client)
            results.append({
                "test": "Incoming",
                "ok": True,
                "message": "Incoming mail looks good.",
            })
        except Exception as e:
            results.append({
                "test": "Incoming",
                "ok": False,
                "message": f"Could not reach the inbox: {format_error(e)}",
            })

    async def _test_exchange(self, handler: dict, results: list[dict]):
        try:
            account = await connect_exchange(
                server=handler.get("imap_server", ""),
                username=handler.get("username", ""),
                password=handler.get("password", ""),
            )
            loop = asyncio.get_event_loop()
            await loop.run_in_executor(None, lambda: account.inbox.total_count)
            results.append({
                "test": "Incoming",
                "ok": True,
                "message": "Exchange inbox looks good.",
            })
        except Exception as e:
            results.append({
                "test": "Incoming",
                "ok": False,
                "message": f"Could not reach the Exchange inbox: {format_error(e)}",
            })

    def _smtp_config(self, handler: dict) -> SmtpConfig:
        smtp_server = handler.get("smtp_server") or handler.get("imap_server", "")
        return SmtpConfig(
            server=smtp_server,
            port=int(handler.get("smtp_port", 587)),
            username=handler.get("username", ""),
            password=handler.get("password", ""),
        )

    async def _test_smtp(self, handler: dict, results: list[dict]):
        try:
            error = await test_smtp(self._smtp_config(handler))
            if error:
                results.append({
                    "test": "Outgoing",
                    "ok": False,
                    "message": f"Could not sign in for sending mail: {error}",
                })
            else:
                results.append({
                    "test": "Outgoing",
                    "ok": True,
                    "message": "Outgoing mail looks good.",
                })
        except Exception as e:
            results.append({
                "test": "Outgoing",
                "ok": False,
                "message": f"Could not sign in for sending mail: {format_error(e)}",
            })

    async def _test_send(self, handler: dict, results: list[dict]):
        try:
            error = await send_reply(
                config=self._smtp_config(handler),
                to=handler.get("username", ""),
                subject="Agent Zero - Connection Test",
                body="This is a test email from Agent Zero email integration.",
            )
            if error:
                results.append({
                    "test": "Send test email",
                    "ok": False,
                    "message": f"Could not send the test email: {error}",
                })
            else:
                results.append({
                    "test": "Send test email",
                    "ok": True,
                    "message": "Test email sent to this inbox.",
                })
        except Exception as e:
            results.append({
                "test": "Send test email",
                "ok": False,
                "message": f"Could not send the test email: {format_error(e)}",
            })

