from helpers.api import ApiHandler, Input, Output, Request
from werkzeug.datastructures import FileStorage

from plugins._plugin_installer.helpers.install import (
    get_plugin_hub_index,
    install_from_git,
    install_uploaded_zip,
    update_from_git,
)

class PluginInstall(ApiHandler):
    """Plugin installation API. Handles ZIP upload, Git clone, and index fetch."""

    async def process(self, input: Input, request: Request) -> Output:
        action = input.get("action", "") or request.form.get("action", "")

        try:
            if action == "install_zip":
                return self._install_zip(request)
            elif action == "install_git":
                return self._install_git(input)
            elif action == "update_plugin":
                return self._update_git(input)
            elif action == "fetch_index":
                return self._fetch_index(input)
            else:
                return {"success": False, "error": f"Unknown action: {action}"}
        except ValueError as e:
            return {"success": False, "error": str(e)}
        except Exception as e:
            return {"success": False, "error": f"Installation failed: {e}"}

    def _install_zip(self, request: Request) -> dict:
        if "plugin_file" not in request.files:
            return {"success": False, "error": "No file provided"}

        plugin_file: FileStorage = request.files["plugin_file"]
        if not plugin_file.filename:
            return {"success": False, "error": "No file selected"}

        return install_uploaded_zip(plugin_file)

    def _install_git(self, input: dict) -> dict:
        git_url = (input.get("git_url", "") or "").strip()
        git_token = (input.get("git_token", "") or "").strip() or None
        plugin_name = input.get("plugin_name", "")
        thumbnail_url = (input.get("thumbnail_url") or "").strip()
        if not git_url:
            return {"success": False, "error": "Git URL is required"}

        return install_from_git(url=git_url, token=git_token, plugin_name=plugin_name, thumbnail_url=thumbnail_url)

    def _update_git(self, input: dict) -> dict:
        return update_from_git(input.get("plugin_name", ""))

    def _fetch_index(self, input: dict) -> dict:
        return {"success": True, **get_plugin_hub_index()}

from __future__ import annotations

import asyncio
import uuid

from helpers.api import ApiHandler, Request, Response
from helpers.ws_manager import ConnectionNotFoundError, get_shared_ws_manager
from plugins._a0_connector.helpers.ws_runtime import (
    active_launcher_gateway_sid,
    all_host_browser_metadata,
    clear_pending_browser_op,
    store_pending_browser_op,
)


_BROWSER_OP_EVENT = "connector_browser_op"
_BROWSER_OP_TIMEOUT_SECONDS = 8.0
_BROWSER_FAMILIES = {"chrome", "opera", "edge"}


class HostBrowserSetup(ApiHandler):
    async def process(self, input: dict, request: Request) -> dict | Response:
        del request
        browser_family = str(input.get("browser_family", "") or "").strip().lower()
        if browser_family not in _BROWSER_FAMILIES:
            return Response("browser_family must be chrome, opera, or edge", status=400)

        connectors = [
            item
            for item in all_host_browser_metadata()
            if "open_remote_debugging" in (item.get("features") or [])
        ]
        gateway_sid = active_launcher_gateway_sid()
        gateway = next((item for item in connectors if item.get("sid") == gateway_sid), None)
        if gateway is not None:
            sid = str(gateway["sid"])
        elif len(connectors) == 1:
            sid = str(connectors[0]["sid"])
        elif connectors:
            return Response(
                "Multiple hosts are connected; disconnect all but the host to configure",
                status=409,
            )
        else:
            return Response(
                "Connect or update Launcher or A0 CLI before opening a host browser setup page",
                status=409,
            )

        op_id = str(uuid.uuid4())
        payload = {
            "op_id": op_id,
            "context_id": "_browser_settings",
            "action": "open_remote_debugging",
            "browser_family": browser_family,
        }
        loop = asyncio.get_running_loop()
        future: asyncio.Future[dict] = loop.create_future()
        store_pending_browser_op(op_id, sid=sid, future=future, loop=loop)
        try:
            await get_shared_ws_manager().emit_to(
                "/ws",
                sid,
                _BROWSER_OP_EVENT,
                payload,
                handler_id=f"{self.__class__.__module__}.{self.__class__.__name__}",
            )
            result = await asyncio.wait_for(future, timeout=_BROWSER_OP_TIMEOUT_SECONDS)
        except ConnectionNotFoundError:
            return Response("The connected host disconnected", status=409)
        except asyncio.TimeoutError:
            return Response("The connected host did not open the browser setup page in time", status=504)
        finally:
            clear_pending_browser_op(op_id)

        if not result.get("ok", False):
            return Response(
                str(result.get("error") or "The connected host could not open the browser setup page"),
                status=409,
            )
        return {"ok": True, "result": result.get("result", {})}

"""API handler for chat compaction."""
from helpers.api import ApiHandler, Input, Output, Request, Response
from agent import AgentContext
from plugins._chat_compaction.helpers.compactor import (
    MIN_COMPACTION_TOKENS,
    get_compaction_stats,
    run_compaction,
)


class CompactChat(ApiHandler):
    """Compact the current chat history into a summarized message."""

    async def process(self, input: Input, request: Request) -> Output:
        ctxid = input.get("context", "")
        action = input.get("action", "compact")

        if not ctxid:
            return Response("Missing context id", 400)

        context = AgentContext.get(ctxid)
        if not context:
            return Response("Context not found", 404)

        if context.is_running():
            return Response("Cannot compact while agent is running", 409)

        visible_count = len(context.log.logs)
        if visible_count <= 1:
            return Response("Not enough messages to compact", 400)

        # Gate both stats and compact — no point opening the modal for tiny chats
        stats = await get_compaction_stats(context)
        if stats["token_count"] < MIN_COMPACTION_TOKENS:
            return {
                "ok": False,
                "message": f"Not enough content to compact (minimum {MIN_COMPACTION_TOKENS:,} tokens)",
            }

        if action == "stats":
            return {"ok": True, "stats": stats}

        elif action == "compact":
            use_chat_model = input.get("use_chat_model", True)
            preset_name = input.get("preset_name") or None

            context.run_task(
                _run_compaction_task, context, use_chat_model, preset_name
            )

            return {"ok": True, "message": "Compaction started"}

        else:
            return Response(f"Unknown action: {action}", 400)


async def _run_compaction_task(context, use_chat_model: bool, preset_name: str | None):
    """Wrapper to run compaction and handle errors."""
    try:
        await run_compaction(context, use_chat_model, preset_name)
    except Exception as e:
        context.log.log(
            type="error",
            heading="Compaction Failed",
            content=str(e),
        )
        from helpers.state_monitor_integration import mark_dirty_all
        mark_dirty_all(reason="plugins._chat_compaction.compact_chat_error")

from __future__ import annotations

from helpers.api import ApiHandler, Request
from plugins._oauth.helpers.providers import CODEX_PROVIDER_ID, get_provider


class PollDeviceLogin(ApiHandler):
    async def process(self, input: dict, request: Request) -> dict:
        raw_provider_id = _provider_id(input)
        try:
            return get_provider(raw_provider_id).poll_login(input, request).to_dict()
        except Exception as exc:
            return {
                "ok": False,
                "provider_id": _provider_id_label(raw_provider_id),
                "error": str(exc),
            }


def _provider_id(input: dict) -> object:
    if "provider_id" not in input or input.get("provider_id") is None:
        return CODEX_PROVIDER_ID
    value = input.get("provider_id")
    if isinstance(value, str) and not value.strip():
        return CODEX_PROVIDER_ID
    return value


def _provider_id_label(value: object) -> str:
    if value is None:
        return CODEX_PROVIDER_ID
    text = str(value).strip()
    return text or CODEX_PROVIDER_ID
